// Indicatore globale delle operazioni asincrone in corso.
let contatoreAttivita = 0;
let ascoltatoreAttivita = null;
function impostaAscoltatoreAttivita(fn) {
  ascoltatoreAttivita = fn;
  if (fn) fn(contatoreAttivita > 0);
}
function segnalaAttivita(delta) {
  contatoreAttivita += delta;
  if (ascoltatoreAttivita) ascoltatoreAttivita(contatoreAttivita > 0);
}

async function inviaEmailIscrizione(tipo, iscrizioneId, richiedeSessione = false) {
  const headers = { 'Content-Type': 'application/json' };
  if (richiedeSessione) {
    const { data } = await supabase.auth.getSession();
    const token = data?.session?.access_token;
    if (token) headers.Authorization = `Bearer ${token}`;
  }
  const r = await fetch('/api/send-email', {
    method: 'POST',
    headers,
    body: JSON.stringify({ tipo, iscrizioneId }),
  });
  const dati = await r.json().catch(() => ({}));
  if (!r.ok || !dati?.ok) throw new Error(dati?.errore || 'Email non inviata');
  return dati;
}


async function inviaEmailPacchetto(acquistoId) {
  const { data } = await supabase.auth.getSession();
  const token = data?.session?.access_token;
  if (!token) throw new Error('Sessione non disponibile');
  const r = await fetch('/api/send-package-email', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
    body: JSON.stringify({ acquistoId }),
  });
  const dati = await r.json().catch(() => ({}));
  if (!r.ok || !dati?.ok) throw new Error(dati?.errore || 'Comunicazione pacchetto non inviata');
  return dati;
}

// Il backend restituisce le righe del foglio con i nomi delle colonne
// (snake_case): queste funzioni le convertono nella forma usata dal frontend.
function mappaEvento(r) {
  return {
    id: r.id, data: r.data, ora: r.ora, tipo: r.tipo_lezione, luogo: r.luogo || "",
    postiTotali: Number(r.posti_totali) || 0, postiOccupati: Number(r.posti_occupati) || 0,
  };
}

function mappaCane(r) {
  return {
    cane: r.cane_nome, conduttore: r.proprietario_nome, email: r.proprietario_email, telefono: r.proprietario_telefono,
    razza: r.razza || "", eta: r.eta || "", sesso: r.sesso || "", sterilizzato: r.sterilizzato || "",
    motivoRichiesta: r.motivo_richiesta || "", saluteTerapie: r.salute_terapie || "", comportamento: r.comportamento || "",
    dataNascitaConduttore: r.data_nascita_conduttore || "", dataNascitaCane: r.data_nascita_cane || "",
    microchip: r.microchip || "", brevettoAcs: r.brevetto_acs || "", brevettoSalvataggio: r.brevetto_salvataggio || "",
    scadenzaBrevetto: r.scadenza_brevetto || "",
    // Queste informazioni non hanno ancora una colonna nel foglio Anagrafica del backend:
    // per ora restano solo visualizzate/modificate lato app, senza persistere.
    lezioniResidue: 0, lezioniTotali: 0,
    quotaAssociativa: { importo: 0, versato: 0, scadenza: "", stato: "da versare" },
    quotaPacchetto: { importo: 0, versato: 0, scadenza: "", stato: "da versare" },
  };
}

function mappaPrenotazione(r) {
  return {
    id: r.id, slotId: r.disponibilita_id, cliente: r.cliente_nome, cane: r.cane_nome,
    email: r.cliente_email || "", telefono: r.cliente_telefono, stato: r.stato, confermatoDa: r.confermato_da,
    annullatoDa: r.annullato_da || "", dataAnnullamento: r.data_annullamento || "",
    dataPrenotazione: r.data_prenotazione || "", acquistoId: r.acquisto_id || "",
    carnetPrima: Number(r.carnet_prima), carnetDopo: Number(r.carnet_dopo), movimentoPacchetto: Number(r.movimento_carnet) || 0,
    creditoRestituito: r.credito_restituito === true,
    nuovo: r.stato === "in sospeso",
    razza: r.razza || "", eta: r.eta || "", sesso: r.sesso || "", sterilizzato: r.sterilizzato || "",
    motivoRichiesta: r.motivo_richiesta || "", saluteTerapie: r.salute_terapie || "",
    comportamento: r.comportamento || "", microchip: r.microchip || ""
  };
}

function mappaCarnet(r) {
  return { id: r.id, nome: r.nome, numeroLezioni: Number(r.numero_lezioni) || 0, prezzo: Number(r.prezzo) || 0 };
}

function mappaAcquisto(r) {
  return {
    id: r.id, cane: r.cane_nome, carnetId: r.carnet_id, data: r.data_acquisto,
    lezioniTotali: Number(r.lezioni_totali) || 0, lezioniResidue: Number(r.lezioni_residue) || 0,
    numeroPacchetto: r.numero_pacchetto || null,
    statoPacchetto: r.stato_pacchetto || (r.pagato ? 'attivo' : 'assegnato'),
    documentoUrl: r.documento_url || '', bonificoUrl: r.bonifico_url || '',
    adesioneAccettata: r.adesione_accettata === true,
  };
}

