function CreditRing({ residue, totali }) {
  const pct = Math.max(0, Math.min(1, totali ? residue / totali : 0));
  const deg = pct * 360;
  return (
    <div className="relative w-16 h-16 shrink-0 rounded-full grid place-items-center"
      style={{ background: `conic-gradient(${COLORS.green} ${deg}deg, #E4E9E7 ${deg}deg 360deg)` }}>
      <div className="w-[52px] h-[52px] rounded-full bg-white grid place-items-center flex-col">
        <span className="font-mono text-[13px] leading-none font-semibold" style={{ color: COLORS.navy }}>
          {residue}
        </span>
        <span className="font-mono text-[9px] leading-none text-slate-400 mt-0.5">/{totali}</span>
      </div>
    </div>
  );
}

