  async function creaIstruttore(e) {
    e.preventDefault();
    if (!isAdmin) return;
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData.session?.access_token;
      if (!token) throw new Error("Sessione scaduta: accedi di nuovo.");
      const res = await fetch("/api/admin-user", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ action: "create", ...formIstruttore })
      });
      const risposta = await res.json();
      if (!res.ok || !risposta.ok) throw new Error(risposta.errore || "Creazione utente fallita");
      setIstruttori((prev) => [...prev, risposta.profilo]);
      registraLog(istruttoreLoggato.nome, "creazione", "Utente", `Nuovo account: ${formIstruttore.nome} (${formIstruttore.username}, ruolo ${formIstruttore.ruolo})`);
      setFormIstruttore({ nome: "", username: "", password: "", ruolo: "istruttore" });
      setNuovoIstruttore(false);
    } catch (err) {
      alert(err?.message || "Non è stato possibile creare l'utente.");
    }
  }


  async function eliminaIstruttore(usernameDaEliminare) {
    if (!isAdmin) return;
    if (usernameDaEliminare === istruttoreLoggato.username) {
      alert("Non puoi eliminare il tuo stesso account mentre sei collegato.");
      return;
    }
    if (!window.confirm(`Eliminare l'account "${usernameDaEliminare}"? L'azione non si può annullare.`)) return;
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData.session?.access_token;
      if (!token) throw new Error("Sessione scaduta: accedi di nuovo.");
      const res = await fetch("/api/admin-user", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ action: "delete", username: usernameDaEliminare })
      });
      const risposta = await res.json();
      if (!res.ok || !risposta.ok) throw new Error(risposta.errore || "Eliminazione utente fallita");
      setIstruttori((prev) => prev.filter((i) => i.username !== usernameDaEliminare));
      registraLog(istruttoreLoggato.nome, "eliminazione", "Utente", `Eliminato account: ${usernameDaEliminare}`);
    } catch (err) {
      alert(err?.message || "Non è stato possibile eliminare l'utente.");
    }
  }


