/* ---------- Vista Iscrizione (modulo pubblico di iscrizione ai corsi) ---------- */

// Facoltativo: se compili questi dati, nel passo 3 del modulo compare il riquadro
// con le coordinate per il bonifico. Se lasci l'IBAN vuoto, il riquadro non appare.
const DATI_BONIFICO = { intestatario: "", iban: "", causale: "Iscrizione corso ACS + nome del cane" };

function leggiComeDataUrl(file) {
  return new Promise((resolve, reject) => {
    const lettore = new FileReader();
    lettore.onload = () => resolve(lettore.result);
    lettore.onerror = () => reject(new Error("Impossibile leggere il file."));
    lettore.readAsDataURL(file);
  });
}

// Le foto della ricevuta vengono ridimensionate (max 1600 px, JPEG) per non appesantire
// l'invio; i PDF restano com'erano, con un limite di dimensione.
async function preparaRicevuta(file) {
  const LIMITE_PDF = 2.5 * 1024 * 1024;
  if (file.type === "application/pdf") {
    if (file.size > LIMITE_PDF) throw new Error("Il PDF è troppo grande (massimo 2,5 MB).");
    return await leggiComeDataUrl(file);
  }
  if (!file.type.startsWith("image/")) {
    throw new Error("Formato non supportato: carica una foto/immagine oppure un PDF.");
  }
  const dataUrl = await leggiComeDataUrl(file);
  const img = await new Promise((resolve, reject) => {
    const i = new Image();
    i.onload = () => resolve(i);
    i.onerror = () => reject(new Error("Immagine non leggibile. Prova con un altro file."));
    i.src = dataUrl;
  });
  const scala = Math.min(1, 1600 / Math.max(img.width, img.height));
  const canvas = document.createElement("canvas");
  canvas.width = Math.round(img.width * scala);
  canvas.height = Math.round(img.height * scala);
  canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
  return canvas.toDataURL("image/jpeg", 0.8);
}

function formattaEuro(valore) {
  return (Number(valore) || 0).toLocaleString("it-IT", { style: "currency", currency: "EUR" });
}

